// Block (composition) — a step that asks for a number on a keypad, such as a phone number, an amount, a
// code or a PIN. It is the most repeated composite in an ordering and payment product: POS
// dialogs, entry screens, a terminal's home and every PIN screen. It arranges StepHeader, a read-only TextField that shows the value, NumericKeypad, and the
// submit and decline Buttons; the keypad is the only input, so the field never takes typing or opens a
// system keyboard.
//
// `format` owns what the field shows. A phone number keeps a fixed `phonePrefix` the person never types
// (such as `010-`); an amount gets grouping and the unit; a PIN shows
// dots and submits itself once complete. Because a PIN acts at its length with no button press, the
// step's description should say so (WCAG 3.2.2), e.g. "4자리를 누르면 바로 확인해요". The decline is
// a single outline Button in one place, whatever its wording.
import { useId, useState } from "react";
import { useLocale } from "react-aria-components";
import type { ReactNode, Ref } from "react";
import { Button } from "../components/Button";
import { ButtonGroup } from "../components/ButtonGroup";
import { NumericKeypad } from "../components/NumericKeypad";
import { StepHeader } from "../components/StepHeader";
import { TextField } from "../components/TextField";
import { Stack } from "../layouts/Stack";
import "./KeypadEntry.css";

type KeypadEntryFormat = "digits" | "phone" | "amount" | "pin";

const DEFAULT_MAX: Record<KeypadEntryFormat, number> = { digits: 12, phone: 8, amount: 9, pin: 4 };

/** The text the field shows for a digit string in a format. A PIN shows one dot per digit. */
// ponytail: phone grouping is the Korean mobile 4-4 after the prefix; add a pattern prop for other plans.
export function formatKeypadValue(
  digits: string,
  format: KeypadEntryFormat,
  { unit = "", phonePrefix = "", locale }: { unit?: string; phonePrefix?: string; locale?: string } = {},
): string {
  switch (format) {
    case "phone": {
      // Everything past the first four shows, so a longer maxLength never hides a digit.
      const a = digits.slice(0, 4);
      const b = digits.slice(4);
      return `${phonePrefix ? `${phonePrefix}-` : ""}${a}${b ? `-${b}` : ""}`;
    }
    case "amount":
      return digits ? `${new Intl.NumberFormat(locale).format(Number(digits))}${unit}` : "";
    case "pin":
      return "•".repeat(digits.length);
    default:
      return digits;
  }
}

export interface KeypadEntryBaseProps {
  /** Context line above the title, e.g. the points to earn. */
  eyebrow?: ReactNode;
  /** What the person is asked to enter. */
  title: ReactNode;
  /** One or two lines under the title. */
  description?: ReactNode;
  /** The field's name, e.g. "Phone number". Also the keypad's accessible name. */
  label: string;
  /** Accessible name of the keypad's delete key. */
  deleteLabel: string;
  /**
   * For `pin`: what is announced after each key, given the digits entered and the length, such as
   * "4자리 중 2자리". Never the digits themselves.
   *
   * @default (count, max) => `${count}/${max}`
   */
  pinStatus?: (count: number, max: number) => string;
  /** Unit after an amount, e.g. "원". */
  unit?: string;
  /** For `phone`: the fixed leading digits the person never types, e.g. "010". */
  phonePrefix?: string;
  /** Maximum digits. Defaults by format: phone 8 (after 010), pin 4, amount 9, digits 12. */
  maxLength?: number;
  /** Controlled digits (no formatting). */
  value?: string;
  /** Initial digits when uncontrolled. */
  defaultValue?: string;
  /** Called with the digits after every key. */
  onChange?: (digits: string) => void;
  /** Label of the submit Button. Without it there is no submit Button. Ignored for `pin`, which submits itself. */
  submitLabel?: string;
  /** Label of the decline action, e.g. "Not now". Without it there is no decline. */
  declineLabel?: string;
  /** Called when the person declines. */
  onDecline?: () => void;
  /**
   * Shown under the field when the entry is rejected, and announced once when set. Clear it in
   * `onChange`: while it stays set the live region holds it, so the next entry is silent and a second
   * identical failure is not announced again.
   */
  errorMessage?: string;
  /**
   * Size of the keypad and the buttons. `large` on a customer device read from arm's length (a counter
   * screen, a kiosk); `medium` in a staff dialog.
   *
   * @default "medium"
   */
  size?: "small" | "medium" | "large";
  /**
   * Header alignment. `center` on a customer screen.
   *
   * @default "start"
   */
  align?: "start" | "center";
  /** Additional class (optional). sd-keypad-entry is always preserved. */
  className?: string;
  /** Forwarded to the root element. */
  ref?: Ref<HTMLElement>;
}

/**
 * A PIN submits itself at its length, so it must say what happens then: `onSubmit` is required. A
 * caller holding the format in a `KeypadEntryFormat` variable narrows it first (`format === "pin"`), or
 * the union does not resolve.
 */
export type KeypadEntryProps = KeypadEntryBaseProps &
  (
    | {
        /** A PIN: shown as dots, announced as a count, submitted at its length. */
        format: "pin";
        /** Called with the digits when the PIN reaches `maxLength`. */
        onSubmit: (digits: string) => void;
      }
    | {
        /**
         * What is entered and how it shows: `phone` keeps a fixed `phonePrefix`, `amount` groups digits in
         * the locale's style and adds `unit`, `pin` shows dots.
         *
         * @default "digits"
         */
        format?: Exclude<KeypadEntryFormat, "pin">;
        /** Called with the digits when the submit Button is pressed. */
        onSubmit?: (digits: string) => void;
      }
  );

export function KeypadEntry({
  eyebrow,
  title,
  description,
  label,
  deleteLabel,
  pinStatus = (count, max) => `${count}/${max}`,
  format = "digits",
  unit = "",
  phonePrefix = "",
  maxLength,
  value,
  defaultValue = "",
  onChange,
  submitLabel,
  onSubmit,
  declineLabel,
  onDecline,
  errorMessage,
  size = "medium",
  align = "start",
  className,
  ref,
}: KeypadEntryProps) {
  const [inner, setInner] = useState(defaultValue);
  const digits = value ?? inner;
  const max = maxLength ?? DEFAULT_MAX[format];
  const headingId = useId();
  const { locale } = useLocale();
  const complete = digits.length >= max;
  const shown = formatKeypadValue(digits, format, { unit, phonePrefix, locale });
  // A PIN submits itself at its length, so it has no submit Button to press a second time.
  const submit = submitLabel && format !== "pin";

  const change = (next: string) => {
    if (value === undefined) setInner(next);
    onChange?.(next);
    if (format === "pin" && next.length >= max) {
      // Uncontrolled, a PIN clears before it is submitted, so a rejected PIN can be typed again; a
      // consumer mirroring it hears the clear first, and an error set in onSubmit is the last word.
      if (value === undefined) {
        setInner("");
        onChange?.("");
      }
      onSubmit?.(next);
    }
  };

  return (
    <Stack
      as="section"
      ref={ref}
      gap="large"
      aria-labelledby={headingId}
      className={className ? `sd-keypad-entry ${className}` : "sd-keypad-entry"}
    >
      {/* Over the field, so the header takes the inset (rule 8); centred, both sides keep it centred. */}
      <>
        <StepHeader id={headingId} size={size} eyebrow={eyebrow} title={title} description={description} align={align} />
      </>
      <TextField
        className="sd-keypad-entry__field"
        size={size}
        label={label}
        value={shown}
        isReadOnly
        isInvalid={Boolean(errorMessage)}
        errorMessage={errorMessage}
      />
      {/* Focus stays on the keypad, so the field changes silently; this says what it now holds: the
          error when the entry is rejected (FieldError is not a live region), the field's name when it
          is cleared, a count for a PIN (never its digits), else the value. */}
      <span className="sd-visually-hidden" aria-live="polite">
        {errorMessage ?? (digits.length === 0 ? label : format === "pin" ? pinStatus(digits.length, max) : shown)}
      </span>
      <NumericKeypad
        className="sd-keypad-entry__keypad"
        aria-label={label}
        deleteLabel={deleteLabel}
        purpose={format === "amount" ? "amount" : "digits"}
        value={digits}
        onChange={change}
        maxLength={max}
        size={size}
      />
      {(submit || declineLabel) && (
        <ButtonGroup className="sd-keypad-entry__actions" layout={align === "center" ? "center" : "end"}>
          {declineLabel && (
            <Button variant="secondary" size={size} onPress={onDecline}>
              {declineLabel}
            </Button>
          )}
          {submit && (
            <Button size={size} isDisabled={format === "phone" ? !complete : digits.length === 0} onPress={() => onSubmit?.(digits)}>
              {submitLabel}
            </Button>
          )}
        </ButtonGroup>
      )}
    </Stack>
  );
}

/* Layout only (block-contract.md §3, §5): Stack places header, field, keypad and actions; the keypad
   takes the space left so it stays large on a tall customer screen. */
.sd-keypad-entry {
  inline-size: 100%;
}

.sd-keypad-entry__keypad {
  flex: 1;
}
